	fmt.Fprintf(wr, "DIGEST\tREPO\tTAG\tCREATED\t\n")
	for _, bundle := range bundles {
		fmt.Fprintf(wr, "%s\t%s\t%s\t%s\t\n", bundle.Digest.Hex()[:7], bundle.Repository, bundle.Tag, bundle.CreatedAt)
